def score(guess, answer):
    res = ['B'] * 5
    left = {}
    for i in range(5):
        if guess[i] == answer[i]:
            res[i] = 'G'
        else:
            left[answer[i]] = left.get(answer[i], 0) + 1
    for i in range(5):
        if res[i] != 'G' and left.get(guess[i], 0) > 0:
            res[i] = 'Y'
            left[guess[i]] -= 1
    return ''.join(res)

def run(obs, nodes, memory):
    if not obs['history']:
        return {'guess': 'salet', 'remaining': len(obs['answer_pool'])}
    cand = [w for w in obs['answer_pool'] if all(score(h['guess'], w) == h['feedback'] for h in obs['history'])]
    return {'guess': cand[0], 'remaining': len(cand)}
